    }
    * { box-sizing: border-box; }
    body { margin: 0; }
    button, input, textarea { font: inherit; }
    button { cursor: pointer; }
    :focus-visible { outline: 2px solid #744cde; outline-offset: 4px; }
    .frame { width: min(1096px, calc(100% - 64px)); margin: auto; }
    .top { border-bottom: 1px solid var(--line); background: #fcfaff; }
    .top .frame { min-height: 66px; display: flex; align-items: center; }
    .brand { display: flex; gap: 11px; align-items: center; font-size: 14px; font-weight: 800; font-family: Manrope, sans-serif; }
    .brand-icon { width: 33px; height: 33px; display: grid; place-items: center; border-radius: 10px; background: #ede5ff; color: var(--purple); }
    main { padding: 41px 0 40px; }
    h1, h2, h3, p { margin: 0; }
    h1, h2, h3 { font-family: Manrope, system-ui, sans-serif; }
    h1 { font-size: clamp(34px, 5vw, 52px); font-weight: 800; line-height: 1.08; letter-spacing: -.068em; }
    .intro p { margin-top: 12px; color: var(--muted); font-size: 16px; }
    .workspace { display: grid; grid-template-columns: minmax(295px, 355px) minmax(0, 1fr); gap: 20px; margin-top: 29px; }
    .panel { border: 1px solid var(--line); border-radius: 19px; background: #fff; }
    .controls { padding: 22px 23px; }
    .panel-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
    .panel-head h2 { font-size: 16px; font-weight: 800; letter-spacing: -.025em; }
    .reset { display: inline-flex; align-items: center; gap: 6px; border: 0; padding: 5px 0 5px 5px; background: none; color: var(--purple); font-size: 12px; font-weight: 700; }
