    .sliders { margin-top: 20px; display: grid; gap: 16px; }
    .value { border-radius: 6px; background: #f4effc; min-width: 54px; text-align: center; padding: 4px 6px; color: #554274; font: 11px var(--mono); }
    label { font-size: 13px; font-weight: 700; }
    input[type=\"range\"] { appearance: none; display: block; width: 100%; height: 6px; margin: 12px 0 7px; border-radius: 100px; background: linear-gradient(to right, #8961e7 0 var(--fill), #eee8f5 var(--fill) 100%); cursor: pointer; }
    input[type=\"range\"]::-webkit-slider-thumb { appearance: none; width: 15px; height: 15px; background: #7549dc; border: 2px solid white; box-shadow: 0 0 0 1px #7549dc; border-radius: 50%; }
    input[type=\"range\"]::-moz-range-thumb { width: 11px; height: 11px; background: #7549dc; border: 2px solid white; box-shadow: 0 0 0 1px #7549dc; border-radius: 50%; }
    .color-field { margin-top: 18px; padding-top: 15px; border-top: 1px solid #f0eaf5; }
    .color-control { display: flex; align-items: center; gap: 10px; margin-top: 9px; height: 39px; padding: 5px 9px; border: 1px solid var(--line); border-radius: 8px; }
    input[type=\"color\"] { width: 28px; height: 26px; padding: 0; background: none; border: 0; cursor: pointer; }
    input[type=\"color\"]::-webkit-color-swatch-wrapper { padding: 1px; }
    input[type=\"color\"]::-webkit-color-swatch { border: 1px solid #0002; border-radius: 5px; }
    input[type=\"color\"]::-moz-color-swatch { border: 1px solid #0002; border-radius: 5px; }
    .hex { font: 12px var(--mono); text-transform: uppercase; color: #554a6c; }
    .preview { overflow: hidden; display: flex; flex-direction: column; }
    .preview .panel-head { min-height: 54px; padding: 0 20px; }
    .live { display: flex; gap: 6px; align-items: center; color: #5f497f; font-size: 12px; }
    .live::before { content: \"\"; width: 7px; height: 7px; border-radius: 50%; background: #8a5ae7; }
    .stage { flex: 1; min-height: 366px; display: grid; place-items: center; padding: 24px; border-top: 1px solid var(--line); background: radial-gradient(circle, #c1afd866 1px, transparent 1.2px) 0 0 / 17px 17px, radial-gradient(ellipse at center, #f2e9ff, #f8f4fd 78%); }
    .pricing { width: min(100%, 302px); padding: 23px; background: #fff; border: 1px solid #ebe3f4; }
    .plan { display: flex; align-items: center; justify-content: space-between; gap: 9px; }
    .plan h3 { font-size: 18px; font-weight: 800; letter-spacing: -.035em; }
    .badge { white-space: nowrap; border-radius: 20px; padding: 4px 9px; background: #eee6ff; color: #613ebd; font-size: 10px; font-weight: 800; }
    .price { display: flex; gap: 6px; align-items: baseline; margin-top: 10px; }
    .price strong { font: 800 40px/1 Manrope, sans-serif; letter-spacing: -.075em; }
    .price span, .summary { color: var(--muted); font-size: 12px; }
    .summary { margin-top: 8px; }
    .features { margin: 15px 0; padding: 13px 0 0; border-top: 1px solid #eee8f3; list-style: none; display: grid; gap: 7px; color: #514761; font-size: 12px; }
    .features li { display: flex; align-items: center; gap: 8px; }
    .features ryugi-icon { color: var(--purple); }
    .plan-cta { display: block; text-align: center; border-radius: 8px; padding: 9px; background: #6f45d5; color: #fff; font-size: 12px; font-weight: 700; }
    .export { margin-top: 20px; padding: 16px 19px 17px; border-radius: 17px; background: #211934; color: #f7f1ff; }
    .export .panel-head h2 { display: flex; align-items: center; gap: 8px; }
    .export .panel-head h2 ryugi-icon { color: #c4a3ff; }
    .copy { border: 1px solid #52436a; background: #392c50; color: #fff; border-radius: 8px; padding: 7px 10px; display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 700; }
    .copy:hover { background: #4a3868; }
    .export-actions { display: flex; align-items: center; gap: 10px; }
    #copy-status { text-align: right; color: #decaff; font-size: 12px; }
    #css-output { display: block; width: 100%; height: 55px; margin-top: 10px; padding: 8px 11px; border: 1px solid #413453; border-radius: 8px; background: #1a132b; color: #decaff; resize: none; font: 12px/18px var(--mono); }
    @media (max-width: 700px) {
      .frame { width: calc(100% - 32px); }
      main { padding-top: 30px; }
      .workspace { grid-template-columns: 1fr; }
      .preview { order: -1; position: sticky; top: 0; z-index: 1; }
      .stage { min-height: 225px; padding: 12px; }
      .pricing { padding: 13px 18px; }
      .price strong { font-size: 30px; }
      .features { margin: 8px 0; padding-top: 6px; gap: 3px; }
      .preview .panel-head { min-height: 41px; }
    }
    @media (max-height: 540px) and (max-width: 700px) {
      .preview { position: static; }
    }
  </style>
</head>
<body>
  <header class=\"top\">
    <div class=\"frame\">
      <div class=\"brand\"><span class=\"brand-icon\" aria-hidden=\"true\"><ryugi-icon name=\"layers\" size=\"18\"></ryugi-icon></span>Shadow Studio</div>
    </div>
  </header>
  <main class=\"frame\">
    <div class=\"intro\">
      <h1>Pricing card shadows</h1>
      <p>Tune the shadow and corners of a pricing card, then copy the CSS.</p>
    </div>
    <div class=\"workspace\">
      <form id=\"shadow-controls\" class=\"panel controls\" aria-labelledby=\"controls-title\">
        <div class=\"panel-head\">
          <h2 id=\"controls-title\">Shadow controls</h2>
          <button class=\"reset\" id=\"reset\" type=\"reset\"><ryugi-icon name=\"rotate-ccw\" size=\"13\" aria-hidden=\"true\"></ryugi-icon>Reset</button>
        </div>
        <div class=\"sliders\">
          <div>
            <div class=\"panel-head\"><label for=\"elevation\">Elevation</label><output class=\"value\" id=\"elevation-value\" for=\"elevation\">16px</output></div>
            <input id=\"elevation\" type=\"range\" min=\"0\" max=\"48\" value=\"16\">
          </div>
          <div>
            <div class=\"panel-head\"><label for=\"blur\">Blur</label><output class=\"value\" id=\"blur-value\" for=\"blur\">36px</output></div>
            <input id=\"blur\" type=\"range\" min=\"0\" max=\"96\" value=\"36\">
          </div>
          <div>
            <div class=\"panel-head\"><label for=\"spread\">Spread</label><output class=\"value\" id=\"spread-value\" for=\"spread\">−8px</output></div>
            <input id=\"spread\" type=\"range\" min=\"-32\" max=\"32\" value=\"-8\">
          </div>
          <div>
            <div class=\"panel-head\"><label for=\"radius\">Corner radius</label><output class=\"value\" id=\"radius-value\" for=\"radius\">20px</output></div>
            <input id=\"radius\" type=\"range\" min=\"0\" max=\"48\" value=\"20\">
          </div>
        </div>
        <div class=\"color-field\">
          <label for=\"shadow-color\">Shadow colour</label>
          <div class=\"color-control\">
            <input id=\"shadow-color\" type=\"color\" value=\"#b8a6d9\">
            <output class=\"hex\" id=\"color-value\" for=\"shadow-color\">#B8A6D9</output>
          </div>
        </div>
      </form>
      <section class=\"panel preview\" aria-labelledby=\"preview-title\">
        <div class=\"panel-head\">
          <h2 id=\"preview-title\">Pricing card preview</h2>
          <span class=\"live\">Live</span>
        </div>
        <div class=\"stage\">
          <article class=\"pricing\" id=\"pricing-card\" style=\"box-shadow: 0 16px 36px -8px #b8a6d9; border-radius: 20px;\">
            <div class=\"plan\"><h3>Pro</h3><span class=\"badge\">Most popular</span></div>
            <div class=\"price\"><strong>"'$24</strong><span>/ month</span></div>
            <p class="summary">For teams ready to do more together.</p>
            <ul class="features">
              <li><ryugi-icon name="check" size="14" aria-hidden="true"></ryugi-icon>Unlimited projects</li>
              <li><ryugi-icon name="check" size="14" aria-hidden="true"></ryugi-icon>Advanced analytics</li>
              <li><ryugi-icon name="check" size="14" aria-hidden="true"></ryugi-icon>Priority support</li>
            </ul>
            <span class="plan-cta">Get started</span>
          </article>
        </div>
      </section>
    </div>
    <section class="export" aria-labelledby="export-title">
      <div class="panel-head">
        <h2 id="export-title"><ryugi-icon name="code" size="17" aria-hidden="true"></ryugi-icon>Generated CSS</h2>
        <div class="export-actions">
          <span id="copy-status" role="status"></span>
          <button class="copy" id="copy-css" type="button"><ryugi-icon name="copy" size="14" aria-hidden="true"></ryugi-icon>Copy CSS</button>
        </div>
      </div>
      <textarea id="css-output" readonly spellcheck="false" aria-labelledby="export-title" wrap="off">box-shadow: 0 16px 36px -8px #b8a6d9;
border-radius: 20px;</textarea>
    </section>
  </main>
  <script>
    const form = document.getElementById('"'shadow-controls');
    const sliders = Array.from(form.querySelectorAll('input[type=\"range\"]'));
    const [elevation, blur, spread, radius] = sliders;
    const color = document.getElementById('shadow-color');
    const colorValue = document.getElementById('color-value');
    const card = document.getElementById('pricing-card');
    const css = document.getElementById('css-output');
    const copyButton = document.getElementById('copy-css');
    const copyStatus = document.getElementById('copy-status');

    function render() {
      for (const slider of sliders) {
        const fraction = (slider.valueAsNumber - Number(slider.min)) / (Number(slider.max) - Number(slider.min));
        slider.style.setProperty('--fill', fraction * 100 + '%');
        document.getElementById(slider.id + '-value').value = slider.value.replace('-', '−') + 'px';
      }

      const shadow = "'`0 ${elevation.value}px ${blur.value}px ${spread.value}px ${color.value}`;
      const corners = radius.value + '"'px';
      colorValue.value = color.value.toUpperCase();
      card.style.boxShadow = shadow;
      card.style.borderRadius = corners;
      css.value = "'`box-shadow: ${shadow};'"\\nborder-radius: "'${corners};`;
      copyStatus.textContent = '"'';
    }

    form.addEventListener('input', render);
    form.addEventListener('change', render);
    form.addEventListener('reset', () => requestAnimationFrame(render));

    copyButton.addEventListener('click', async () => {
      const value = css.value;
      try {
        await navigator.clipboard.writeText(value);
      } catch {
        css.focus();
        css.select();
        try {
          if ("'!document.execCommand('"'copy')) {
            copyStatus.textContent = 'CSS selected. Use your copy shortcut.';
            return;
          }
        } catch {
          copyStatus.textContent = 'CSS selected. Use your copy shortcut.';
          return;
        }
        copyButton.focus();
      }
      if (css.value === value) copyStatus.textContent = 'Copied';
    });

    render();
  </script>
</body>
</html>
EOF"

